*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS21100.xml";
scwin.gAllChk = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 표면이자율 미확정리스트 조회 한다.
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS21100_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listCoupnRtNotYetDecided" + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue() + "&{P}STD_CD=" + $c.stf.getObjectValue(txb_STD_CD);

    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};


/********************************************** 
 * 함수명  : fn_SetBgColor_list
 * 설명      : 미확정 목록의 배경색 설정
 ***********************************************/
scwin.fn_SetBgColor_list = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_Grid.getTotalCol(); i++) {
        arrColID.push(grd_Grid.getColumnID(i));
    }

    //미확정목록 중에 이미 표면이자율이 등록된 로우의 배경색 Light Yellow로 설정
    for (var j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(FINAL_STAT,'ERROR','#FFFF99','NORMAL','#FFFFFF',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};



/********************************************** 
 * 함수명   : ins_all_send_mail
 * 설명       : 일괄 메일 전송
 ***********************************************/
scwin.ins_all_send_mail = function() {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    if (scwin.fn_chkValid() == false) {
        $c.win.alert("이메일 발송대상을 체크하세요.");
        return;
    }
    if (!confirm("잘못된 형식의 이메일인 경우 전송되지 않을 수 있습니다.\n\n이메일을 발송하시겠습니까?")) {
        return;
    }
    trs_autosave.Action = "/EtcInfoAction.do?method=registerAllSendMail" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_autosave.KeyName = "toinb_dataid4";
    trs_autosave.KeyValue = "JSP(I:pInputMaster=dts_List)";
    trs_autosave.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_autosave.Post();
};


/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : elsdls 표준코드 일괄 발급 체크대상을 알아낸다.
 ***********************************************/
scwin.fn_chkValid = function() {
    var cnt = 0;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            cnt++;
        }
    }
    //alert("cnt " +cnt);
    if (eval(cnt) > 0) {
        return true;
    } else {
        return false;
    }
};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 설정한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드  
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SelectAll
 * 설명       : 체크박스 전체선택
 ***********************************************/
scwin.fn_SelectAll = function() {
    grd_Grid.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_List.getTotalRow(); i++) {
            dts_List.setCellData(i + 1, "CHK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_List.getTotalRow(); i++) {
            dts_List.setCellData(i + 1, "CHK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Grid.Redraw = true;
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    edt_SDATE.focus();
    scwin.ins_search();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert('dts_List.OnLoadCompleted('+rowcount+')');
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리
    scwin.fn_SetBgColor_list(); //그리드 배경색 설정

};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row == 0) return;
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    fn_GetPar = fn_GetParam;
    //alert(STD_CD);
    ins_ViewIsuMaster("채권", STD_CD);
};
scwin.btn_Mail_onclick = function() {
    scwin.ins_all_send_mail();
};
scwin.trs_autosave_OnFail = function() {
    alert_tr_error(trs_autosave);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, "표면이자율미확정목록", "", "8");
};
scwin.trs_autosave_OnFail = function() {
    alert_tr_error(trs_autosave);
};
scwin.trs_autosave_OnSuccess = function() {
    $c.win.alert("이메일발송이 완료되었습니다.");
    scwin.ins_search();
};
scwin.txb_STD_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_STD_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.btn_SelectedAll_onclick = function() {
    scwin.fn_SelectAll();
};
